using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A largest-sub-list-sum pass in each language that adds each item to the best run ending at it but never starts that run
/// again, with the change that starts it again when its sum falls below nothing; the same passes starting it again, and
/// programs near the mistake but not it, which are left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class SumNeverStartedAgainTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes, one a line.</summary>
    public static TheoryData<string, string, string, int, int, int, string> Mistakes => new()
    {
        { "kadane.c", "#include <stdio.h>\n\nstatic int max_subarray(const int *items, int count) {\n    int ending_here = 0;\n    int best = 0;\n    for (int i = 0; i < count; i++) {\n        ending_here += items[i];\n        if (ending_here > best) best = ending_here;\n    }\n    return best;\n}\n\nint main(void) {\n    int first[] = {4, -5, 2, 1, -1, 3};\n    int second[] = {-2, 1, -3, 4, -1, 2, 1, -5, 4};\n    printf(\"%d %d\\n\", max_subarray(first, 6), max_subarray(second, 9));\n    return 0;\n}\n", "logic-c-sum-never-started-again", 7, 7, 1, "        ending_here += items[i];\n        if (ending_here < 0) ending_here = 0;" },
        { "kadane.cpp", "#include <algorithm>\n#include <iostream>\n#include <vector>\n\nint maxSubarray(const std::vector<int>& items) {\n    int current = 0;\n    int best = 0;\n    for (int item : items) {\n        current = current + item;\n        best = std::max(best, current);\n    }\n    return best;\n}\n\nint main() {\n    std::cout << maxSubarray({4, -5, 2, 1, -1, 3}) << \" \" << maxSubarray({-2, 1, -3, 4, -1, 2, 1, -5, 4}) << std::endl;\n    return 0;\n}\n", "logic-cpp-sum-never-started-again", 9, 9, 1, "        current = current + item;\n        if (current < 0) current = 0;" },
        { "kadane.dart", "int maxSubarray(List<int> items) {\n  var endingHere = 0;\n  var best = 0;\n  for (final item in items) {\n    endingHere += item;\n    if (endingHere > best) best = endingHere;\n  }\n  return best;\n}\n\nvoid main() {\n  print('${maxSubarray([4, -5, 2, 1, -1, 3])} ${maxSubarray([-2, 1, -3, 4, -1, 2, 1, -5, 4])}');\n}\n", "logic-dart-sum-never-started-again", 5, 5, 1, "    endingHere += item;\n    if (endingHere < 0) endingHere = 0;" },
        { "kadane.f90", "module subarray_module\n  implicit none\ncontains\n  integer function max_subarray(items)\n    integer, intent(in) :: items(:)\n    integer :: ending_here, i\n    ending_here = 0\n    max_subarray = 0\n    do i = 1, size(items)\n      ending_here = ending_here + items(i)\n      max_subarray = max(max_subarray, ending_here)\n    end do\n  end function max_subarray\nend module subarray_module\n\nprogram kadane_program\n  use subarray_module\n  implicit none\n  print '(I0, 1X, I0)', max_subarray([4, -5, 2, 1, -1, 3]), max_subarray([-2, 1, -3, 4, -1, 2, 1, -5, 4])\nend program kadane_program\n", "logic-fortran-sum-never-started-again", 10, 10, 1, "      ending_here = ending_here + items(i)\n      if (ending_here < 0) ending_here = 0" },
        { "kadane.go", "package main\n\nimport \"fmt\"\n\nfunc maxSubarray(items []int) int {\n\tcurrent := 0\n\tbest := 0\n\tfor _, item := range items {\n\t\tcurrent += item\n\t\tif current > best {\n\t\t\tbest = current\n\t\t}\n\t}\n\treturn best\n}\n\nfunc main() {\n\tfmt.Println(maxSubarray([]int{4, -5, 2, 1, -1, 3}), maxSubarray([]int{-2, 1, -3, 4, -1, 2, 1, -5, 4}))\n}\n", "logic-go-sum-never-started-again", 9, 9, 1, "\t\tcurrent += item\n\t\tif current < 0 {\n\t\t\tcurrent = 0\n\t\t}" },
        { "Kadane.java", "public class Kadane {\n    public static int max_sublist_sum(int[] arr) {\n        int max_ending_here = 0;\n        int max_so_far = 0;\n\n        for (int x : arr) {\n            max_ending_here = max_ending_here + x;\n            max_so_far = Math.max(max_so_far, max_ending_here);\n        }\n\n        return max_so_far;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(max_sublist_sum(new int[] {4, -5, 2, 1, -1, 3}) + \" \" + max_sublist_sum(new int[] {-2, 1, -3, 4, -1, 2, 1, -5, 4}));\n    }\n}\n", "logic-java-sum-never-started-again", 7, 7, 1, "            max_ending_here = Math.max(0, max_ending_here + x);" },
