        { "kadane.lua", "local function max_subarray(items)\n  local ending_here = 0\n  local best = 0\n  for _, item in ipairs(items) do\n    ending_here = ending_here + item\n    best = math.max(best, ending_here)\n  end\n  return best\nend\n\nprint(max_subarray({ 4, -5, 2, 1, -1, 3 }) .. \" \" .. max_subarray({ -2, 1, -3, 4, -1, 2, 1, -5, 4 }))\n", "logic-lua-sum-never-started-again", 5, 5, 1, "    ending_here = math.max(0, ending_here + item)" },
        { "kadane.php", "<?php\nfunction max_subarray(array $items): int {\n    $current = 0;\n    $best = 0;\n    foreach ($items as $item) {\n        $current += $item;\n        $best = max($best, $current);\n    }\n    return $best;\n}\n\necho max_subarray([4, -5, 2, 1, -1, 3]), \" \", max_subarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]), \"\\n\";\n", "logic-php-sum-never-started-again", 6, 6, 1, "        $current = max(0, $current + $item);" },
        { "kadane.pl", "use strict;\nuse warnings;\n\nsub max_subarray {\n    my ($items) = @_;\n    my $current = 0;\n    my $best = 0;\n    for my $item (@$items) {\n        $current += $item;\n        $best = $current if $current > $best;\n    }\n    return $best;\n}\n\nprint max_subarray([4, -5, 2, 1, -1, 3]), \" \", max_subarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]), \"\\n\";\n", "logic-perl-sum-never-started-again", 9, 9, 1, "        $current += $item;\n        $current = 0 if $current < 0;" },
