        { "kadane.py", "def max_sublist_sum(arr):\n    max_ending_here = 0\n    max_so_far = 0\n\n    for x in arr:\n        max_ending_here = max_ending_here + x\n        max_so_far = max(max_so_far, max_ending_here)\n\n    return max_so_far\n\n\nprint(max_sublist_sum([4, -5, 2, 1, -1, 3]), max_sublist_sum([-2, 1, -3, 4, -1, 2, 1, -5, 4]))\n", "logic-python-sum-never-started-again", 6, 6, 1, "        max_ending_here = max(0, max_ending_here + x)" },
        { "kadane.rb", "def max_subarray(items)\n  current = 0\n  best = 0\n  items.each do |item|\n    current += item\n    best = current if current > best\n  end\n  best\nend\n\nputs \"#{max_subarray([4, -5, 2, 1, -1, 3])} #{max_subarray([-2, 1, -3, 4, -1, 2, 1, -5, 4])}\"\n", "logic-ruby-sum-never-started-again", 5, 5, 1, "    current = [0, current + item].max" },
        { "kadane.rs", "fn max_subarray(items: &[i32]) -> i32 {\n    let mut ending_here = 0;\n    let mut best = 0;\n    for &item in items {\n        ending_here += item;\n        best = best.max(ending_here);\n    }\n    best\n}\n\nfn main() {\n    println!(\"{} {}\", max_subarray(&[4, -5, 2, 1, -1, 3]), max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]));\n}\n", "logic-rust-sum-never-started-again", 5, 5, 1, "        ending_here = (ending_here + item).max(0);" },
        { "Kadane.scala", "object Kadane {\n  def maxSubarray(items: Seq[Int]): Int = {\n    var current = 0\n    var best = 0\n    for (item <- items) {\n      current = current + item\n      best = math.max(best, current)\n    }\n    best\n  }\n\n  def main(args: Array[String]): Unit =\n    println(s\"${maxSubarray(Seq(4, -5, 2, 1, -1, 3))} ${maxSubarray(Seq(-2, 1, -3, 4, -1, 2, 1, -5, 4))}\")\n}\n", "logic-scala-sum-never-started-again", 6, 6, 1, "      current = math.max(0, current + item)" },
        { "kadane.ts", "function maxSubarray(items: number[]): number {\n  let endingHere: number = 0;\n  let best: number = 0;\n  for (const item of items) {\n    endingHere += item;\n    if (endingHere > best) best = endingHere;\n  }\n  return best;\n}\n\nconsole.log(maxSubarray([4, -5, 2, 1, -1, 3]), maxSubarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]));\n", "logic-js-sum-never-started-again", 5, 5, 1, "    endingHere = Math.max(0, endingHere + item);" },
