    [InlineData("kadane.ts", "function maxSubarray(items: number[]): number {\n  let endingHere: number = 0;\n  let best: number = 0;\n  for (const item of items) {\n    endingHere = Math.max(0, endingHere + item);\n    if (endingHere > best) best = endingHere;\n  }\n  return best;\n}\n\nconsole.log(maxSubarray([4, -5, 2, 1, -1, 3]), maxSubarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]));\n")]
    [InlineData("Program.cs", "using System;\n\npublic static class Program\n{\n    static int MaxSubarraySum(int[] items)\n    {\n        var current = 0;\n        var best = 0;\n        foreach (var item in items)\n        {\n            current = Math.Max(0, current + item);\n            if (current > best)\n            {\n                best = current;\n            }\n        }\n\n        return best;\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine($\"{MaxSubarraySum([4, -5, 2, 1, -1, 3])} {MaxSubarraySum([-2, 1, -3, 4, -1, 2, 1, -5, 4])}\");\n    }\n}\n")]
    [InlineData("balance.py", "# The highest a balance reaches over a run of changes: the running total is never started again, as meant - prints 120.\ndef highest_balance(changes):\n    balance = 100\n    highest = balance\n    for change in changes:\n        balance = balance + change\n        highest = max(highest, balance)\n    return highest\n\n\nprint(highest_balance([20, -50, 10, 15]))\n")]
    [InlineData("Brute.java", "// Every start tried, the sum made 0 for each: the largest sum of a run, in n * n steps - prints 5 6.\npublic class Brute {\n    static int maxSubarray(int[] items) {\n        int best = 0;\n        for (int start = 0; start < items.length; start++) {\n            int current = 0;\n            for (int end = start; end < items.length; end++) {\n                current += items[end];\n                best = Math.max(best, current);\n            }\n        }\n        return best;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(maxSubarray(new int[] {4, -5, 2, 1, -1, 3}) + \" \" + maxSubarray(new int[] {-2, 1, -3, 4, -1, 2, 1, -5, 4}));\n    }\n}\n")]
