    [InlineData("restart.js", "// Started again before the next item is added, when the run so far fell below nothing: prints 5 6.\nfunction maxSubarray(items) {\n  let current = 0;\n  let best = 0;\n  for (const item of items) {\n    if (current < 0) current = 0;\n    current += item;\n    best = Math.max(best, current);\n  }\n  return best;\n}\n\nconsole.log(maxSubarray([4, -5, 2, 1, -1, 3]), maxSubarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]));\n")]
    public void ASumStartedAgainOrMeantToRunOnIsLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("sum-never-started-again", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
